    AND he.contract_id IN ('CCR2CH4GQVCZHG7CHFVMNANCK45CU5DVKXZIIITDZQAU3CEJZ7RQH2MQ', 'CC22BLZAFTS7M6Z25HOMKDLV65PBP5CIHFER2OTZB5IRNL3YBWDXKDFF', 'CA75VVHLWSM7W6ULNQI7ZJYDFOMQCCPKIDDDHBAL5KOKHWWKWQ5S7MHO', 'CBBXZDNNIVCGGLLCH43KTH6WDZ5MFVYFQ5LTGD236A4A6OJMH2K4H6LA', 'CDAUN7SBYWRAVKJA453ZGLEP4LFCR25ANTI6EIHKTWSSTWHYJXLD3EXT', 'CDO6MTO4RYHFWWIG4DA3ZDHJ7GQMWA3BCZW4YTSBHEEDOJZV4BTJZB7M', 'CC22KKT4G3MSL5STSZDOC4KA5CTLCFTQX4ASASIGOE7Z3HI7HOY5F33H', 'CCOLSF35JVRGLONMJJMFYXUAEQ5IM4QOMYEWMXEFJEOQK3WVN4EJ3OUR', 'CAMUA6N6SLCMSIQRICXIQBRYYG3SCEPILS2HJTBXGMCOBCRWQUHAS2OJ', 'CD2JLIZ5TSF746SVPNU224CY3ZIXTEII37CC4DNCTSDRLK4NAXBCQZLB', 'CBV7CK2DDLODRLTWFBWE7CN5WKN5B6O26ERTULNQIWJQ7ZBTHTGQ5YFI', 'CDGIQQBPGXATIEXWTFN5O6J7LM5IMQLMVIQ47Q4H44VIMMOBZ4N6KRVZ', 'CCUVVQJNVI3UBXHZ6LDW2BTULOKMFZWVYLY26QTP62AWUQCDPVNZWEPJ', 'CBBHUYY3YE7AOCLHFFVTOFHPMV3WBANNDIQBJ3NCNLXC7BLHRAM5YD7M', 'CB5NNLVWQWN26VBOI576UVA4EGDGPKOHGNVTVYXREXAN2TO3XT6SCJL4', 'CBVKO35SAF2ZT75FCLCGLYQG3S6B32YZTOJ2G5F7M746UGBRAWZ5BNZ6', 'CAKWXQDEVVUF2ABUEM3M2G7QJGJNDZNNVXJZYG4Z4QP6K54QTWV4DW2S', 'CDVBYETOFG7UYJAD6CMOAQZXBHEK3PD5ZDZKWMWIY5OXIWATPX4VGMY2', 'CCQ4WKGF5PDJZ3PTDQBOOWD6HE67DEB3QHOGLF2VAWO2RBCGDT2DPDTI', 'CBVZXBW5E5Q72J5ETZT4ZJLNS6GTLQC5BLUOERJNFQMMTKQCVY4N5YSX', 'CA5MIPAAG3UULVAHK7U3U6VBBM52YIHMCZOOSHNTPUSLYR7NKNHVD6WK', 'CCAQO6MKWCD463JZEIY5JUSU425H77LNYM3R6ZNQPO4KBU5C3SAEJDDB', 'CAPT5THGW7WOCX47TICCB5JZZK4Y24CHQIBSM57Y472WFFV6FGTRKJQD', 'CAUBW4ARD42U2UEIA7GDUB5LNKTRTVYJHXKL3CV27YZRDFADDGKLZWFD', 'CBGBQUEHEDIMA2P5JVHROPYVENY7Y3EA3DDYEMIW2HICRKFW7YDI635B', 'CAPUAZDFH4VBQTC7PYL7UM2KSXER2ZY3D462WW6DCE2HGUSO646S4F2X', 'CAWWOFOEGWPPNP6QKVHTJYB7UHRXC6W6EAFMUPGHMJL7K46E6UCOSNDM', 'CCMPJ2PZDNG7DCQWU6YHF56U3QULE3JGMUVEZWBIWQOYHU6Z6QLEOEJQ', 'CD6BHNV26Z7FOUU7VCFMYPRIB5JOG7724R42O5EJ4KGQXK3USO4NYOLS', 'CA5R5L7QE7WC2M4YAPSBITV7M2R6LX5366UURH3REHQMOJV6R5QWTH2K', 'CAXJ2FDV6S3L46EFEFRXUBLQ5U5CZLZOG35RPCJRNQVLM5MH2HCK5I7J', 'CDEXGN6YJXIPSMJZPU4NTJH6IVD47ZOG6GNTTMYK4X3U4JKLKD34F4XT', 'CCWJAQURY64U4VWI5GDLF42SH4RWFJZTYXO5BGA7SLNLVBGGV2L4EBIP', 'CAFLJXGUAURAMBA3AIHC7ZJOAQKGZ7WEFFGMH5XRC35IMNU7PWIBXVTP', 'CABMZD6BYKKLHRJNS5MURYOBX77NPAH767AI7EVFGWV3WZV55QFN5YNE', 'CCT74MCKWWPKHK5T7LXBPXK7AAPZIH35HJZY5CRZGVEJ4UUCMFQXBNVH', 'CCI2P2I4MWU3J2RQ6YKJXQN46CB42LWAFCUYNWY2J2JVHZBIDR74TLBG', 'CCKC4L6LI5ZNFKJCE7TVOEGGNJQPVHCCRJWMDYWEBL26SY62INCJLZMP', 'CCF7MYFIILNDCDZ37QGYJQRYW455MPHA5PJIQ5D3KB3KEYLZA2WB26S2', 'CCFWRAC3MB7JSPKAWSWT3MCRHVQECG3SU2JAMNAL3K2UHBQIYHBSR5LY', 'CA6LYAEDN7XHOKD5TNRFBM3IDFD22VRVVXTGPGK77FZFC7X2OYUQ7BAZ', 'CBTZO2GHYS23PW4QSHRNT66X62YZQJU7X3ZCZOKJTNEXKLR4WBYV54D7', 'CBQIPFKHCXBLXJKSFSZJJLODGZDA6C33D5TUL3VAPXM25LH2YKNAROC2', 'CDDPO65MGM3HYYMFJJB7Y7NCRV2DAJ7YAFZYQQRMBLCR3WHFIPAZQCTS', 'CDSOL7SBO2ZEASXAFZNDXGJUMIM7YOUBHQOXCCVQEKKYACIR43ZBH6MZ', 'CALM7JTAJC7AJ7ZGTQKXZNNILJUCD2AZNN7QA7FVM3YYIJBCJGUABEDH', 'CAWN3BM2ADBMA4CQZLIHTBXA3BQHV4VAPK42LWT5ONAKZW6PH2BBCKLS', 'CAOGXY6DW2KWUVOWCGGPLW7MIJNP7XCMXY736LNLOKYEQA3CBKXVIDEA', 'CCXRRORTOXXP53HEKJ6RCG7CDRWZAJHIS4N7PDL32PUNMNN7VWPJVQWS', 'CCRKQ2RHBWB5ZCHOSBSYEC2QNVSU3MGVUF56BWWKJMJIJ3ZF2A6W7KEC', 'CBOLCGXDSRU22SLUIJMFCJBOOURQLZHX5ZFIFJBYK2VAB3AEK5M2T5GM', 'CDMJRRH5MAJLB7T5SQAWQOOL7UJ3BABGTURSVKIE6AEDSXESDDJIBVCT', 'CD7ZJUQEJODTJXWJMDJRV7UHCANOBX3FC6KXJV3DMIFX3JXUWMF3U3T5', 'CCLXJ4F5STIZ7WWC5D2J57VCLLFIQMWUI5PSYJORPZTAUUQTS2XFU5ZK', 'CACU7KU33MFWMOP334RNQT7CZV3M7DNDAAXL5O3I4ATQRZCMXFJI4RMZ', 'CBRKPTX4TWYEVGDTTVLSBVN6RKTFC2PKD6F5ZRSGBHQE7GC2UYMALTXY', 'CDNHCFJ6LGPV4OWZL2SAQPFQHAUFFVMWGBZFVPA5Z5HTL4A6RWEZYNM4', 'CBVHBZSZOS6KRDJ4D44FU2YLIENOVSSLM3UGKW6XQMVIFUAMWIWCVH2U')
    AND he.type_string = 'ContractEventTypeContract'
    AND he.successful = TRUE AND he.in_successful_contract_call = TRUE
    AND json_extract_scalar(he.topics_decoded, '$[0].symbol') IN ('swap', 'mint', 'collect')
),
kv AS (
  SELECT e.contract_id, e.closed_at, e.tx_hash, e.action, xxhash64(to_utf8(e.data_decoded)) AS event_key,
         json_extract_scalar(elem, '$.key.symbol') AS k,
         json_extract_scalar(elem, '$.val.address') AS v_addr,
         COALESCE(TRY(CAST(json_extract_scalar(elem, '$.val.i128') AS DECIMAL(38,0))),
                  TRY(CAST(json_extract_scalar(elem, '$.val.u128') AS DECIMAL(38,0)))) AS v_int
  FROM ev e
  CROSS JOIN UNNEST(CAST(json_extract(e.data_decoded, '$.map') AS array(json))) AS t(elem)
),
pivoted AS (
  SELECT contract_id, closed_at, tx_hash, action, event_key,
    MAX(CASE WHEN k = 'sender' THEN v_addr END) AS sender,
    MAX(CASE WHEN k = 'recipient' THEN v_addr END) AS recipient,
    MAX(CASE WHEN k = 'amount0' THEN v_int END) AS amount0,
    MAX(CASE WHEN k = 'amount1' THEN v_int END) AS amount1
  FROM kv
  GROUP BY 1, 2, 3, 4, 5
)
SELECT 'sushiswap' AS protocol, p.contract_id, p.closed_at, p.tx_hash,
  CASE p.action WHEN 'collect' THEN p.recipient ELSE p.sender END AS user_address,
  CASE p.action WHEN 'mint' THEN 'add_liquidity' ELSE p.action END AS action,
  CASE p.action WHEN 'swap' THEN 'swapper' ELSE 'lp' END AS role,
  p.contract_id AS pool,
  CASE WHEN p.action <> 'swap' OR p.amount0 > 0 THEN r.token0 ELSE r.token1 END AS token_a,
  CAST(CASE WHEN p.action <> 'swap' THEN p.amount0 WHEN p.amount0 > 0 THEN p.amount0 ELSE p.amount1 END
       * DECIMAL '0.0000001' AS DECIMAL(38,7)) AS amount_a,
  CASE WHEN p.action <> 'swap' OR p.amount0 > 0 THEN r.token1 ELSE r.token0 END AS token_b,
  CAST(CASE WHEN p.action <> 'swap' THEN p.amount1 WHEN p.amount0 > 0 THEN -p.amount1 ELSE -p.amount0 END
       * DECIMAL '0.0000001' AS DECIMAL(38,7)) AS amount_b
FROM pivoted p
LEFT JOIN pools r ON r.pool = p.contract_id
)
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, role, pool, token_a, amount_a, token_b, amount_b,
       'activity' AS row_kind, covered_from, CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata') END AS covered_until, refreshed_at, source_layer
FROM prev
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, role, pool, token_a, amount_a, token_b, amount_b,
       'activity', DATE '2026-03-01', CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata') END, CURRENT_TIMESTAMP, 'archive'
FROM src
WHERE regexp_like(user_address, '^[GC][A-Z2-7]{55}$') AND role IS NOT NULL
UNION ALL
SELECT 'sushiswap', NULL, CAST(NULL AS TIMESTAMP WITH TIME ZONE), NULL, NULL, NULL, NULL, NULL, NULL, CAST(NULL AS DECIMAL(38,7)), NULL, CAST(NULL AS DECIMAL(38,7)),
       'metadata', DATE '2026-03-01', CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'metadata') END, CURRENT_TIMESTAMP, 'archive'
